class Solution:
    def findKthNumber(self, m, n, k):
        def count_le(x):
            total = 0
            for i in range(1, m + 1):
                total += min(n, x // i)
            return total
        for x in range(1, m*n + 1):
            if count_le(x) >= k: return x
        return m*n

solutions.optimal:
class Solution:
    def findKthNumber(self, m, n, k):
        if m > n: m, n = n, m
        def count_le(x):
            total=0
            for i in range(1,m+1):
                total += min(n, x // i)
            return total
        lo,hi=1,m*n
        while lo<hi:
            mid=(lo+hi)//2
            if count_le(mid) >= k: hi=mid
            else: lo=mid+1
        return lo

